import AppKit
let out = CommandLine.arguments[1]
func color(_ hex:UInt32)->NSColor{NSColor(srgbRed:CGFloat((hex>>16)&255)/255,green:CGFloat((hex>>8)&255)/255,blue:CGFloat(hex&255)/255,alpha:1)}
let green=color(0x145A46),navy=color(0x102E43),gold=color(0xC9A34D)
func image(_ name:String,_ w:Int,_ h:Int,_ draw:()->Void){let rep=NSBitmapImageRep(bitmapDataPlanes:nil,pixelsWide:w,pixelsHigh:h,bitsPerSample:8,samplesPerPixel:4,hasAlpha:true,isPlanar:false,colorSpaceName:.deviceRGB,bytesPerRow:0,bitsPerPixel:0)!;NSGraphicsContext.saveGraphicsState();NSGraphicsContext.current=NSGraphicsContext(bitmapImageRep:rep);draw();NSGraphicsContext.restoreGraphicsState();try! rep.representation(using:.png,properties:[:])!.write(to:URL(fileURLWithPath:out+"/"+name+".png"))}
func text(_ s:String,_ rect:NSRect,_ size:CGFloat,_ c:NSColor,_ bold:Bool=true){let style=NSMutableParagraphStyle();style.alignment = .center;let font=NSFont(name:bold ? "Thonburi-Bold":"Thonburi",size:size) ?? NSFont.systemFont(ofSize:size,weight:bold ? .bold:.regular);(s as NSString).draw(in:rect,withAttributes:[.font:font,.foregroundColor:c,.paragraphStyle:style])}
func line(_ pts:[NSPoint],_ c:NSColor,_ width:CGFloat=6){let p=NSBezierPath();p.move(to:pts[0]);for pt in pts.dropFirst(){p.line(to:pt)};p.lineWidth=width;p.lineCapStyle = .round;p.lineJoinStyle = .round;c.setStroke();p.stroke()}
func icon(_ kind:String,_ x:CGFloat,_ y:CGFloat,_ scale:CGFloat,_ c:NSColor){NSGraphicsContext.saveGraphicsState();let t=NSAffineTransform();t.translateX(by:x,yBy:y);t.scale(by:scale);t.concat();c.setStroke();let p=NSBezierPath();p.lineWidth=5;p.lineCapStyle = .round;p.lineJoinStyle = .round
switch kind{
case "home":line([NSPoint(x:8,y:43),NSPoint(x:48,y:77),NSPoint(x:88,y:43)],c);line([NSPoint(x:20,y:45),NSPoint(x:20,y:12),NSPoint(x:76,y:12),NSPoint(x:76,y:45)],c);line([NSPoint(x:40,y:12),NSPoint(x:40,y:37),NSPoint(x:57,y:37),NSPoint(x:57,y:12)],c)
case "donate":p.move(to:NSPoint(x:48,y:17));p.curve(to:NSPoint(x:14,y:62),controlPoint1:NSPoint(x:14,y:42),controlPoint2:NSPoint(x:8,y:45));p.curve(to:NSPoint(x:48,y:64),controlPoint1:NSPoint(x:18,y:83),controlPoint2:NSPoint(x:38,y:83));p.curve(to:NSPoint(x:82,y:62),controlPoint1:NSPoint(x:58,y:83),controlPoint2:NSPoint(x:80,y:83));p.curve(to:NSPoint(x:48,y:17),controlPoint1:NSPoint(x:92,y:44),controlPoint2:NSPoint(x:64,y:30));p.stroke()
case "fund":for i in 0..<12{let a=CGFloat(i)*CGFloat.pi/6;line([NSPoint(x:48+32*cos(a),y:48+32*sin(a)),NSPoint(x:48+41*cos(a),y:48+41*sin(a))],c,7)};let ring=NSBezierPath(ovalIn:NSRect(x:18,y:18,width:60,height:60));ring.lineWidth=7;ring.stroke();let ring2=NSBezierPath(ovalIn:NSRect(x:36,y:36,width:24,height:24));ring2.lineWidth=5;ring2.stroke()
case "tables":let r=NSBezierPath(ovalIn:NSRect(x:24,y:24,width:48,height:48));r.lineWidth=5;r.stroke();for i in 0..<8{let a=CGFloat(i)*CGFloat.pi/4;let chair=NSBezierPath(ovalIn:NSRect(x:43+37*cos(a),y:43+37*sin(a),width:10,height:10));c.setFill();chair.fill()}
case "shirts":line([NSPoint(x:28,y:78),NSPoint(x:8,y:62),NSPoint(x:21,y:42),NSPoint(x:31,y:48),NSPoint(x:31,y:14),NSPoint(x:69,y:14),NSPoint(x:69,y:48),NSPoint(x:79,y:42),NSPoint(x:92,y:62),NSPoint(x:72,y:78),NSPoint(x:60,y:71),NSPoint(x:48,y:63),NSPoint(x:39,y:73),NSPoint(x:28,y:78)],c,5)
default:for i in 0..<3{let r=NSBezierPath(roundedRect:NSRect(x:12,y:14+CGFloat(i)*26,width:70,height:16),xRadius:5,yRadius:5);r.lineWidth=4;r.stroke();let dot=NSBezierPath(ovalIn:NSRect(x:22,y:20+CGFloat(i)*26,width:4,height:4));c.setFill();dot.fill()}}
NSGraphicsContext.restoreGraphicsState()}
let menus=[("home","หน้าหลัก"),("donate","ทอดผ้าป่าศิษย์เก่า"),("fund","กองทุนช่างกลโรงงาน"),("tables","จองโต๊ะจีน"),("shirts","จองเสื้อที่ระลึก"),("admin","ผู้ดูแลระบบ")]
for (kind,title) in menus{image("menu-"+kind,640,260){let bg=NSBezierPath(roundedRect:NSRect(x:2,y:2,width:636,height:256),xRadius:32,yRadius:32);NSGradient(starting:green,ending:navy)!.draw(in:bg,angle:0);gold.setStroke();bg.lineWidth=2;bg.stroke();icon(kind,34,82,1,.white);text(title,NSRect(x:135,y:95,width:460,height:65),34,.white);line([NSPoint(x:570,y:42),NSPoint(x:590,y:42),NSPoint(x:590,y:62)],gold,3)};image("icon-"+kind,192,192){icon(kind,0,0,2,green)}}
for (name,c) in [("primary",green),("hover",navy),("gold",gold),("disabled",color(0xD9DFD5))]{image("button-"+name,720,144){let p=NSBezierPath(roundedRect:NSRect(x:2,y:2,width:716,height:140),xRadius:28,yRadius:28);c.setFill();p.fill();if name != "disabled"{gold.withAlphaComponent(0.55).setStroke();p.lineWidth=2;p.stroke()}}}
for (name,c) in [("available",color(0xE8F2E8)),("selected",green),("pending",color(0xF2CF82)),("confirmed",color(0xBC6759))]{image("table-"+name,128,128){for i in 0..<8{let a=CGFloat(i)*CGFloat.pi/4;let p=NSBezierPath(roundedRect:NSRect(x:56+49*cos(a),y:56+49*sin(a),width:16,height:16),xRadius:5,yRadius:5);c.setFill();p.fill()};let p=NSBezierPath(ovalIn:NSRect(x:22,y:22,width:84,height:84));c.setFill();p.fill();gold.withAlphaComponent(0.65).setStroke();p.lineWidth=2;p.stroke()}}
print("Created 20 transparent PNG UI assets")
